 33		file, err := os.CreateTemp(dir, ".navidrome_backup_*.tmp")
 34		if err != nil {
 35			return "", fmt.Errorf("create temporary backup: %w", err)
 36		}
 37		tmpPath := file.Name()
 38		if err := file.Close(); err != nil {
 39			_ = os.Remove(tmpPath)
 40			return "", err
 41		}
 42		defer os.Remove(tmpPath)
