 44		dest, err := sql.Open(Driver, tmpPath)
 45		if err != nil {
 46			return "", fmt.Errorf("open temporary backup: %w", err)
 47		}
 48		srcConn, err := d.readDB.Conn(ctx)
 49		if err != nil {
 50			_ = dest.Close()
 51			return "", fmt.Errorf("open source database: %w", err)
 52		}
 53		destConn, err := dest.Conn(ctx)
 54		if err != nil {
 55			_ = srcConn.Close()
 56			_ = dest.Close()
 57			return "", fmt.Errorf("open temporary backup connection: %w", err)
 58		}
 59		err = sqliteCopy(ctx, destConn, srcConn)
 60		err = errors.Join(err, destConn.Close(), srcConn.Close(), dest.Close())
 61		if err != nil {
 62			return "", fmt.Errorf("copy database to backup: %w", err)
 63		}
 64		info, err := os.Stat(tmpPath)
 65		if err != nil {
 66			return "", fmt.Errorf("inspect temporary backup: %w", err)
 67		}
 68		if info.Size() == 0 {
 69			return "", errors.New("source database is empty")
 70		}
