 80	func (d *db) Restore(ctx context.Context, path string) error {
 81		if path == "" {
 82			return errors.New("backup file path is required")
 83		}
 84		info, err := os.Stat(path)
 85		if err != nil {
 86			return fmt.Errorf("access backup file: %w", err)
 87		}
 88		if !info.Mode().IsRegular() {
 89			return fmt.Errorf("backup file is not a regular file: %s", path)
 90		}
 91		if info.Size() == 0 {
 92			return fmt.Errorf("backup file is empty: %s", path)
 93		}
 94		currentPath := conf.Server.DbPath
 95		if strings.HasPrefix(currentPath, "file:") {
 96			if uri, err := url.Parse(currentPath); err == nil {
 97				currentPath = uri.Path
 98			}
 99		}
100		if current, err := os.Stat(currentPath); err == nil && os.SameFile(info, current) {
101			return errors.New("backup file is the current database")
102		}
103		absPath, err := filepath.Abs(path)
104		if err != nil {
105			return err
106		}
107		uri := (&url.URL{Scheme: "file", Path: filepath.ToSlash(absPath), RawQuery: "mode=ro"}).String()
108		src, err := sql.Open(Driver, uri)
109		if err != nil {
110			return fmt.Errorf("open backup file: %w", err)
111		}
112		defer src.Close()
113		var check string
114		if err := src.QueryRowContext(ctx, "PRAGMA quick_check").Scan(&check); err != nil {
115			return fmt.Errorf("validate backup file: %w", err)
116		}
117		if check != "ok" {
118			return fmt.Errorf("backup file failed integrity check: %s", check)
119		}
120		srcConn, err := src.Conn(ctx)
121		if err != nil {
122			return fmt.Errorf("open backup connection: %w", err)
123		}
124		defer srcConn.Close()
125		destConn, err := d.writeDB.Conn(ctx)
126		if err != nil {
127			return fmt.Errorf("open destination database: %w", err)
128		}
129		defer destConn.Close()
130		if err := sqliteCopy(ctx, destConn, srcConn); err != nil {
131			return fmt.Errorf("restore database: %w", err)
132		}
133		return nil
134	}
